const express = require('express');
const Redis = require('ioredis');

const app = express();
const redis = new Redis(process.env.REDIS_URL);

app.get('/internal/sessions/impersonate/:sid', async (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: 'Super-admin token required' });
  }

  // Validate super-admin token against dedicated audit authority
  const isSuperAdmin = await verifySuperAdminToken(authHeader);
  if (!isSuperAdmin) {
    return res.status(403).json({ error: 'Forbidden: unauthorized impersonation attempt logged' });
  }

  const rawSession = await redis.get(`sess:${req.params.sid}`);
  if (!rawSession) {
    return res.status(404).json({ error: 'Session not found in store' });
  }

  const sessionObj = JSON.parse(rawSession);

  // Log impersonation event for SOC compliance
  await auditLog.recordImpersonation({
    adminId: isSuperAdmin.userId,
    targetSessionId: req.params.sid,
    timestamp: new Date()
  });

  res.cookie('connect.sid', `s:${req.params.sid}`, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    path: '/'
  });

  res.json({
    message: 'Impersonation authorized and logged',
    impersonatedUser: sessionObj.passport ? sessionObj.passport.user : sessionObj.userId
  });
});

async function verifySuperAdminToken(auth) {
  // Verifies cryptographically signed super-admin authorization token
  return auth === `Bearer ${process.env.SUPER_ADMIN_STATIC_KEY}` ? { userId: 'admin_root' } : null;
}

app.listen(9090);
